      "commissionSubtitle": "ನಿಮ್ಮ ಟ್ರಾಫಿಕ್ ಗುಣಮಟ್ಟ ಮತ್ತು ಮಾನಿಟೈಸೇಶನ್ ತಂತ್ರಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುವ ಒಪ್ಪಂದ ರಚನೆಯನ್ನು ಆಯ್ಕೆಮಾಡಿ. ಕಸ್ಟಮ್ ದರಗಳನ್ನು ವಾಲ್ಯೂಮ್, GEO ಮತ್ತು ಸ್ವಾಧೀನ ಚಾನೆಲ್ ಆಧಾರದ ಮೇಲೆ ಚರ್ಚಿಸಲಾಗುತ್ತದೆ.",
      "revshareTitle": "ರೆವೆನ್ಯೂ ಶೇರ್",
      "revshareDesc": "ಉಲ್ಲೇಖಿಸಿದ ಆಟಗಾರರಿಂದ Net Gaming Revenue (NGR) ನ ನಿರಂತರ ಶೇಕಡಾವಾರು ಗಳಿಸಿ. RevShare ನಗದು ಗೇಮ್‌ಪ್ಲೇ GGR ನಿಂದ ಬೋನಸ್ ವೆಚ್ಚವನ್ನು ಕಳೆದು ಲೆಕ್ಕಹಾಕಲಾಗುತ್ತದೆ — ನಿಜವಾದ ಆಟಗಾರ ಮೌಲ್ಯಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ.",
      "revsharePoint1": "ಅರ್ಹತೆಯ ಆಟಗಾರ ಚಟುವಟಿಕೆಯ ಮೇಲೆ ಜೀವನಾವಧಿ ರೆವೆನ್ಯೂ ಶೇರ್",
      "revsharePoint2": "ನಿಮ್ಮ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ GGR, ಬೋನಸ್ ವೆಚ್ಚ ಮತ್ತು NGR ಪಾರದರ್ಶಕ ವಿಭಜನೆ",
      "revsharePoint3": "SEO, ವಿಷಯ ಮತ್ತು ಸಮುದಾಯ-ಚಾಲಿತ ಟ್ರಾಫಿಕ್‌ಗೆ ಆದರ್ಶ",
      "cpaTitle": "CPA (Cost Per Acquisition)",
      "cpaDesc": "ಉಲ್ಲೇಖಿಸಿದ ಆಟಗಾರ ಅರ್ಹತೆಯ ಮೊದಲ ಠೇವಣಿ ಪೂರ್ಣಗೊಳಿಸಿದಾಗ ಸ್ಥಿರ ಒಮ್ಮೆ ಪಾವತಿ ಪಡೆಯಿರಿ. ಮುನ್ಸೂಚಿಸಬಹುದಾದ ಮುಂಗಡ ಆದಾಯ ಬೇಕಾದಾಗ ಪರಿಪೂರ್ಣ.",
      "cpaPoint1": "ಮೊದಲ ಅರ್ಹತೆಯ ಠೇವಣಿಯಲ್ಲಿ ಒಮ್ಮೆ ಪಾವತಿ",
      "cpaPoint2": "ಮುಂಚಿತವಾಗಿ ಒಪ್ಪಿಕೊಂಡ ಸ್ಪಷ್ಟ ಅರ್ಹತಾ ನಿಯಮಗಳು",
      "cpaPoint3": "ಪಾವತಿಸಿದ ಮಾಧ್ಯಮ ಮತ್ತು ಹೆಚ್ಚಿನ-ವಾಲ್ಯೂಮ್ ಸ್ವಾಧೀನ ಫನೆಲ್‌ಗಳಿಗೆ ಉತ್ತಮ",
      "hybridTitle": "ಹೈಬ್ರಿಡ್ (CPA + RevShare)",
      "hybridDesc": "ಅದೇ ಆಟಗಾರರ ಮೇಲೆ ಮುಂಗಡ CPA ಅನ್ನು ನಿರಂತರ RevShare ಜೊತೆ ಸಂಯೋಜಿಸಿ. ತಕ್ಷಣದ ನಗದು ಹರಿವನ್ನು ಸಕ್ರಿಯ ಆಟಗಾರರ ದೀರ್ಘಕಾಲೀನ ಆದಾಯದೊಂದಿಗೆ ಸಮತೋಲನಗೊಳಿಸಿ.",
      "hybridPoint1": "ಮೊದಲ ಠೇವಣಿಯಲ್ಲಿ CPA ಮತ್ತು ಭವಿಷ್ಯದ ಚಟುವಟಿಕೆಯಲ್ಲಿ RevShare",
      "hybridPoint2": "ನಿಮ್ಮ ಟ್ರಾಫಿಕ್ ಪ್ರೊಫೈಲ್‌ಗೆ ಅನುಗುಣವಾಗಿ ಹೊಂದಿಕೊಳ್ಳುವ ವಿಭಜನೆ",
