      "benefit2Title": "ರಿಯಲ್-ಟೈಮ್ Affiliate Portal",
      "benefit2Desc": "ಉಲ್ಲೇಖಿಸಿದ ಆಟಗಾರರು, ಠೇವಣಿಗಳು, ಟರ್ನೋವರ್, GGR, ಬೋನಸ್ ವೆಚ್ಚ, NGR ಮತ್ತು ಕಮಿಷನ್ ಸಂಚಯಗಳನ್ನು ಸಮರ್ಪಿತ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ನಿಂದ ಟ್ರ್ಯಾಕ್ ಮಾಡಿ.",
      "benefit3Title": "ಉಪ-ಅಫಿಲಿಯೇಟ್ ನೆಟ್‌ವರ್ಕ್",
