      "benefit4Desc": "ಮುಚ್ಚಿದ ತಿಂಗಳ ಕಮಿಷನ್‌ಗಳು ಬ್ಯಾಂಕ್ ವರ್ಗಾವಣೆ, ಕ್ರಿಪ್ಟೋ ಅಥವಾ ಇ-ವಾಲೆಟ್ ಮೂಲಕ USD ಪಾವತಿಗೆ ಲಭ್ಯವಾಗುತ್ತವೆ — ಕನಿಷ್ಠ ಮಿತಿಗಳಿಗೆ ಒಳಪಟ್ಟು.",
